NOMBRE = r"\d+(?:[.,]\d+)?"
COTES = re.compile(rf"{NOMBRE}(?:\s*[x×X*]\s*{NOMBRE})+")


def renseigner_formats(apps, schema_editor):
    """Format des tôles existantes, lu dans leur référence ou leur libellé (« S235-3 1500x3000 ») : même règle que
    technique.models.format_tole_depuis_texte."""
    Article = apps.get_model("technique", "Article")
    FormatTole = apps.get_model("decoupe", "FormatTole")
    formats = {}
    for f in FormatTole.objects.all():
        formats.setdefault((f.largeur_mm, f.longueur_mm), f.pk)
        formats.setdefault((f.longueur_mm, f.largeur_mm), f.pk)
    if not formats:
        return
    for article in Article.objects.filter(nature="matiere_premiere", epaisseur__isnull=False, format_tole__isnull=True):
        trouve = None
        for texte in (article.reference, article.libelle):
            for cotes in COTES.findall(texte or ""):
                valeurs = [float(v.replace(",", ".")) for v in re.findall(NOMBRE, cotes)]
                trouve = next((formats[(a, b)] for a, b in zip(valeurs, valeurs[1:]) if min(a, b) >= 100 and (a, b) in formats), None)
                if trouve:
                    break
            if trouve:
                break
        if trouve:
            Article.objects.filter(pk=article.pk).update(format_tole_id=trouve)


